var Taf = require("../../libjce.js");
var TTT = require("../jce/TestJceJce.js").TTT;

var output = function(o) {
    console.log(o.toObject());
}

var readFrom = function(src, dest) {

    var os = new Taf.JceOutputStream();

    src._writeTo(os);

    return dest._readFrom(new Taf.JceInputStream(os.getBinBuffer()));
}

var testUserInfo = function() {
    var info = new TTT.UserInfo();
    info.uid = 10;
    // info.price = 12.34567;
    // info.price = 0.0;
    info.price = 12.3456789;
    info.price2 = 0.912345678;
    // info.price = 1.234;
    // info.price2 = 54.12;
    info.f1 = 98.54321;
    info.f2 = 0.1987;

    info.vd1 = new Taf.List(Taf.Double);
    info.vd1.push(1.23456);
    info.vd1.push(0.9123);

    info.vf1 = new Taf.List(Taf.Float);
    info.vf1.push(87.23456);
    info.vf1.push(234.9123);

    info.mfd = new Taf.Map(Taf.Float, Taf.Double);
    info.mfd.put(1.2345, 2.34567);
    info.mfd.put(2.876501, 123.45678);

    output(info);

    ///////////////////////////////////////////////////////////////////

    info.setPrecision(2);

    var info2 = readFrom(info, TTT.UserInfo);

    output(info2);

    ///////////////////////////////////////////////////////////////////
    console.log("test ud==============");

    var ud = new TTT.UserData();
    ud.info = info;
    ud.flag = "a";
    ud.d1 = 3.22244;
    ud.f1 = 100.113411;
    ud.str1 = "straaaa";

    output(ud);

    console.log("test not set degree==============");

    console.log("ud degree:" + ud.getPrecision());
    console.log("ud info degree:" + ud.info.getPrecision());

    var ud2 = readFrom(ud, TTT.UserData);

    output(ud2);

    console.log("test set degree==============");
    ud.setPrecision(3);

    var ud3 = readFrom(ud, TTT.UserData);

    output(ud3);

    console.log("test parse from c++==============");

}

testUserInfo();
